import {stepAnalytics,localDateKey} from './step-analytics.mjs';
const $=id=>document.getElementById(id),fmt=n=>Math.round(n).toLocaleString('pt-BR');
const value=r=>!r.known?'—':r.lower===r.upper?fmt(r.lower):fmt(r.lower)+'–'+fmt(r.upper);
function el(tag,text,parent,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;parent.append(e);return e;}
function svgEl(tag,attrs,parent){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);return e;}
function drawChart(root,rows,type){root.replaceChildren();root.classList.toggle('line-chart',type==='line');if(!rows.some(r=>r.known)){el('p','Sem passos com dados suficientes para este gráfico.',root,'chart-empty');return;}const max=Math.max(1,...rows.map(r=>r.upper));
 if(type==='bars'){const plot=el('div',undefined,root,'step-bars');plot.style.setProperty('--columns',rows.length);rows.forEach((r,i)=>{const c=el('div',undefined,plot,'step-column'),track=el('div',undefined,c,'step-track'),bar=el('div',undefined,track,'step-bar'+(!r.known?' unknown':''));bar.style.height=Math.max(r.known?2:1,r.upper/max*124)+'px';bar.style.setProperty('--delay',Math.min(i*25,500)+'ms');bar.title=r.fullLabel+': '+value(r);const solid=el('span',undefined,bar);solid.style.height=r.upper?100*r.lower/r.upper+'%':'100%';el('span',r.label,c,'axis-label');});}
 else{const svg=svgEl('svg',{viewBox:'0 0 640 170',preserveAspectRatio:'none','aria-hidden':'true'},root);const x=i=>rows.length===1?320:12+i*(616/(rows.length-1)),y=n=>140-n/max*124;let run=[];const flush=()=>{if(!run.length)return;const path=run.map((i,j)=>(j?'L':'M')+x(i)+','+y(rows[i].upper)).join(' ');if(run.some(i=>rows[i].lower!==rows[i].upper)){const upper=run.map(i=>x(i)+','+y(rows[i].upper)),lower=run.slice().reverse().map(i=>x(i)+','+y(rows[i].lower));svgEl('polygon',{points:[...upper,...lower].join(' '),class:'step-band'},svg);}if(run.length>1)svgEl('path',{d:path,class:'step-line',pathLength:'1'},svg);for(const i of run)svgEl('circle',{cx:x(i),cy:y(rows[i].upper),r:4,class:'step-point'},svg);run=[];};rows.forEach((r,i)=>{if(!r.known){flush();return;}if(run.length&&r.start>rows[run.at(-1)].end)flush();run.push(i);});flush();const axis=el('div',undefined,root,'line-axis');const every=Math.max(1,Math.ceil(rows.length/6));rows.forEach((r,i)=>{if(i%every===0||i===rows.length-1)el('span',r.fullLabel,axis);});}
}
function valuesTable(details,rows){details.replaceChildren();el('summary','Ver valores do gráfico',details);const table=el('table',undefined,details),head=el('thead',undefined,table),tr=el('tr',undefined,head);el('th','Período',tr);el('th','Passos estimados',tr);const body=el('tbody',undefined,table);for(const row of rows){const tr=el('tr',undefined,body);el('td',row.fullLabel,tr);el('td',value(row),tr);}}
export function setupAnalytics(getState){let type='bars';$('analytics-date').value=localDateKey(new Date());
 function render(){let data;try{const s=getState();data=stepAnalytics(s.sessions,s.profile,$('analytics-period').value,$('analytics-date').value);}catch(error){$('analytics-coverage').textContent=error.message;return;}
 $('analytics-date').disabled=data.period==='all';$('analytics-total').textContent=value(data.total);$('analytics-range').textContent=data.label;$('analytics-total-label').textContent=data.missingSessions?'Passos estimados · total parcial':'Passos estimados no período';$('analytics-count').textContent=data.sessionCount+' caminhada(s) finalizada(s) no período';$('analytics-missing').textContent=data.missingSessions?data.missingSessions+' caminhada(s) sem estimativa de passos':'Nenhuma caminhada sem estimativa neste período';
 $('analytics-peak').textContent=data.peakHours.length?(data.peakHours.length>3?data.peakHours.length+' horários empatados':data.peakHours.map(h=>String(h).padStart(2,'0')+'h').join(' / ')):'Sem dados por horário';$('analytics-peak-note').textContent=data.peakHours.length?'Maior volume estimado entre os passos com horário disponível.':'Registros manuais sem horários por trecho não criam picos por hora.';
 $('analytics-title').textContent={day:'Passos por hora',week:'Passos por dia',month:'Passos por dia',year:'Passos por mês',all:'Passos por ano'}[data.period];$('analytics-trend').setAttribute('aria-label',$('analytics-title').textContent+'. Consulte os valores detalhados abaixo.');drawChart($('analytics-trend'),data.trend,type);valuesTable($('analytics-values'),data.trend);
 $('analytics-hour-card').hidden=data.period==='day';drawChart($('analytics-hours'),data.hours,'bars');valuesTable($('analytics-hour-values'),data.hours);
 const untimed=data.untimed.upper>0?' '+(data.untimed.lower===data.untimed.upper?fmt(data.untimed.lower):fmt(data.untimed.lower)+'–'+fmt(data.untimed.upper))+' passo(s) sem localização por hora.':'';$('analytics-coverage').textContent=fmt(data.timedSteps)+' passo(s) com horários aproximados pelo GPS.'+untimed+(data.range?' As faixas permanecem faixas; o gráfico usa o limite superior.':'')+(data.sessionCount?' Dias sem registro não comprovam inatividade.':' Nenhuma caminhada finalizada neste período.');
 }
 $('analytics-period').onchange=$('analytics-date').onchange=render;document.querySelectorAll('[data-chart-type]').forEach(b=>b.onclick=()=>{type=b.dataset.chartType;document.querySelectorAll('[data-chart-type]').forEach(p=>p.setAttribute('aria-pressed',String(p===b)));render();});return {render};}
